async def act(page):
    """
    Apply Purchased On date range 2021-05-01 -> 2022-03-31 on the Orders grid and
    export the Orders grid as CSV using the Export control shown in the page UI.

    This function continues from the current Orders page state (no navigation).
    It uses fully-scoped .get_by_role() chains when clicking ambiguous buttons.
    """
    import asyncio
    from pathlib import Path

    # Desired date range values (Magento admin commonly accepts MM/DD/YYYY)
    from_date = "05/01/2021"
    to_date = "03/31/2022"
    out_filename = "orders_2021-05_to_2022-03.csv"

    # Helper to safely get locator count
    async def safe_count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    # 1) Locate the table that contains the Export controls (cell named "Export to: CSV Export")
    export_cell = page.get_by_role("cell", name="Export to: CSV Export")
    if await safe_count(export_cell) == 0:
        # Fallback: find a table that contains a cell whose inner text includes 'Export to'
        controls_table = None
        tables = page.get_by_role("table")
        for i in range(await safe_count(tables)):
            t = tables.nth(i)
            try:
                # check for any cell that contains the substring 'Export to'
                cells = t.get_by_role("cell")
                for j in range(await safe_count(cells)):
                    c = cells.nth(j)
                    try:
                        txt = (await c.inner_text()) or ""
                    except Exception:
                        txt = ""
                    if 'export to' in txt.lower():
                        controls_table = t
                        break
                if controls_table is not None:
                    break
            except Exception:
                continue
        if controls_table is None:
            raise RuntimeError("Could not locate the Export controls table on the page")
        # narrow the export_cell from the located table
        export_cell = controls_table.get_by_role("cell").filter(has=page.get_by_role("combobox")).filter(has=page.get_by_role("button", name="Export")).nth(0)
    else:
        # derive the containing table for the export controls
        controls_table = page.get_by_role("table").filter(has=export_cell).nth(0)

    # 2) Locate the Orders table (table that has the header link "Purchased On")
    orders_table = None
    tables = page.get_by_role("table")
    for i in range(await safe_count(tables)):
        t = tables.nth(i)
        try:
            if await t.get_by_role("link", name="Purchased On").count() > 0:
                orders_table = t
                break
        except Exception:
            continue
    if orders_table is None:
        raise RuntimeError("Orders table (with header 'Purchased On') not found")

    # 3) Within the orders table, locate the Purchased On filter cell which contains two date textboxes
    # Try to find the cell by exact accessible name first
    purchased_cell = orders_table.get_by_role("cell", name="From: Date selector . To : Date selector .")
    if await safe_count(purchased_cell) == 0:
        # Fallback: scan cells for one having inner text with 'From: Date selector' and 'To'
        purchased_cell = None
        cells = orders_table.get_by_role("cell")
        for i in range(await safe_count(cells)):
            c = cells.nth(i)
            try:
                txt = (await c.inner_text()) or ""
            except Exception:
                txt = ""
            low = txt.lower()
            if 'from: date selector' in low and 'to' in low:
                purchased_cell = c
                break
        if purchased_cell is None:
            # Another fallback: look for a cell that contains an image named 'Date selector' (indicates date inputs nearby)
            for i in range(await safe_count(cells)):
                c = cells.nth(i)
                try:
                    if await c.get_by_role('img', name='Date selector').count() > 0:
                        purchased_cell = c
                        break
                except Exception:
                    continue

    if purchased_cell is None:
        raise RuntimeError('Could not locate the Purchased On filter cell with date inputs')

    # 4) Get the two textboxes inside that purchased_cell and fill them
    textboxes = purchased_cell.get_by_role('textbox')
    if await safe_count(textboxes) < 2:
        raise RuntimeError('Expected two date textboxes in Purchased On filter cell')

    from_input = textboxes.nth(0)
    to_input = textboxes.nth(1)

    await from_input.fill(from_date)
    await to_input.fill(to_date)

    # 5) Click the Search button to apply the filters. The Search button lives in the controls table cell named 'Reset Filter Search'
    search_btn = None
    try:
        reset_cell = controls_table.get_by_role('cell', name='Reset Filter Search')
        if await safe_count(reset_cell) > 0:
            # scoped Search button
            if await reset_cell.get_by_role('button', name='Search').count() > 0:
                search_btn = reset_cell.get_by_role('button', name='Search').nth(0)
    except Exception:
        search_btn = None

    if search_btn is None:
        # fallback: try a page-level Search button
        pg_search = page.get_by_role('button', name='Search')
        if await safe_count(pg_search) > 0:
            search_btn = pg_search.nth(0)

    if search_btn is not None:
        await search_btn.click()
        # allow grid to refresh
        await page.wait_for_load_state('networkidle')
        await asyncio.sleep(0.8)
    else:
        # No explicit Search button found; assume filters auto-apply but wait a moment
        await asyncio.sleep(0.8)

    # 6) Ensure the export combobox is set to CSV and click the scoped Export button capturing the download
    # Use the export_cell locator determined earlier
    if await safe_count(export_cell) == 0:
        # try to find the export cell within controls_table
        export_cell = controls_table.get_by_role('cell').filter(has=page.get_by_role('button', name='Export')).nth(0)

    # Select CSV in the combobox inside the export_cell
    combobox = export_cell.get_by_role('combobox')
    if await safe_count(combobox) > 0:
        try:
            # select_option expects option label/value; choose label 'CSV'
            await combobox.select_option(label='CSV')
        except Exception:
            # ignore and continue; CSV already appears selected in the UI per the accessibility tree
            pass

    # Scoped export button
    export_btn = None
    try:
        if await export_cell.get_by_role('button', name='Export').count() > 0:
            export_btn = export_cell.get_by_role('button', name='Export').nth(0)
    except Exception:
        export_btn = None

    if export_btn is None:
        # fallback: find any Export button in the controls_table
        try:
            if await controls_table.get_by_role('button', name='Export').count() > 0:
                export_btn = controls_table.get_by_role('button', name='Export').nth(0)
        except Exception:
            export_btn = None

    if export_btn is None:
        # final fallback: page-level Export button
        pg_export = page.get_by_role('button', name='Export')
        if await safe_count(pg_export) > 0:
            export_btn = pg_export.nth(0)

    if export_btn is None:
        raise RuntimeError('Export button not found')

    # Click Export and wait for download
    async with page.expect_download() as dd:
        await export_btn.click()
    download = await dd.value
    out_path = Path(out_filename)
    await download.save_as(str(out_path))

    # Read file content with UTF-8 then fallback
    try:
        csv_text = out_path.read_text(encoding='utf-8')
    except Exception:
        csv_text = out_path.read_text(encoding='latin-1')

    return {'filename': str(out_path), 'csv': csv_text}

